import React, { useState } from "react";
import { api } from "@/lib/api";
import { Activity, Moon, Droplets, Heart, Scale, Brain, Apple, TrendingUp, Sparkles } from "lucide-react";
import { toast } from "sonner";

export default function HealthScore() {
  const [form, setForm] = useState({
    sleep_hours: 7, water_glasses: 6, bmi: 22, heart_rate: 72,
    exercise_minutes: 30, stress_level: 3, diet_quality: 3,
  });
  const [scoreData, setScoreData] = useState(null);
  const [loading, setLoading] = useState(false);

  const calculate = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await api.post("/health-score/calculate", form);
      setScoreData(res.data);
    } catch {
      toast.error("Could not calculate health score");
    }
    setLoading(false);
  };

  const num = (v) => (v === "" ? "" : Number(v));
  const setNum = (k, v) => setForm({ ...form, [k]: num(v) });

  const scoreBg = (score) => {
    if (score >= 85) return "from-emerald-400 to-teal-500";
    if (score >= 70) return "from-blue-400 to-indigo-500";
    if (score >= 50) return "from-amber-400 to-orange-500";
    return "from-red-400 to-rose-500";
  };

  const inputs = [
    { key: "sleep_hours", label: "Sleep (hours)", icon: Moon, min: 0, max: 24, step: 0.5 },
    { key: "water_glasses", label: "Water (glasses)", icon: Droplets, min: 0, max: 20, step: 1 },
    { key: "bmi", label: "BMI", icon: Scale, min: 10, max: 50, step: 0.1 },
    { key: "heart_rate", label: "Heart Rate (bpm)", icon: Heart, min: 30, max: 220, step: 1 },
    { key: "exercise_minutes", label: "Exercise (min/day)", icon: Activity, min: 0, max: 240, step: 5 },
    { key: "stress_level", label: "Stress (1-10)", icon: Brain, min: 1, max: 10, step: 1 },
    { key: "diet_quality", label: "Diet Quality (1-5)", icon: Apple, min: 1, max: 5, step: 1 },
  ];

  return (
    <div className="max-w-5xl mx-auto" data-testid="health-score-page">
      <div className="glass-strong rounded-3xl p-6 flex items-center gap-3 mb-6">
        <div className="w-11 h-11 rounded-2xl bg-emerald-100 grid place-items-center">
          <Activity className="w-5 h-5 text-emerald-700" strokeWidth={2.5} />
        </div>
        <div>
          <h1 className="font-display text-3xl">Personalized Health Score</h1>
          <p className="text-sm text-slate-500">Like a credit score — for your health.</p>
        </div>
      </div>

      <div className="grid md:grid-cols-12 gap-5">
        <div className="md:col-span-7 glass rounded-3xl p-6">
          <h2 className="font-display text-xl mb-4">Your Metrics</h2>
          <form onSubmit={calculate} className="space-y-4">
            <div className="grid grid-cols-2 gap-3">
              {inputs.map(({ key, label, icon: Icon, min, max, step }) => (
                <label key={key} className="block">
                  <span className="text-xs font-bold uppercase tracking-wider text-slate-500 flex items-center gap-1">
                    <Icon className="w-3 h-3" /> {label}
                  </span>
                  <input type="number" data-testid={`hs-${key}`} value={form[key]}
                    onChange={(e) => setNum(key, e.target.value)} min={min} max={max} step={step}
                    className="mt-1 w-full px-4 py-2.5 rounded-2xl bg-white/90 border border-white outline-none focus:ring-4 focus:ring-emerald-200 text-sm" />
                </label>
              ))}
            </div>
            <button data-testid="hs-calculate" disabled={loading} type="submit"
              className="w-full py-3 rounded-full bg-gradient-to-r from-emerald-400 to-teal-500 text-white font-bold hover:scale-[1.01] transition disabled:opacity-60">
              {loading ? "Calculating..." : "Calculate My Health Score"}
            </button>
          </form>
        </div>

        <div className="md:col-span-5 space-y-4">
          {scoreData ? (
            <>
              <div className={`glass rounded-3xl p-6 text-center bg-gradient-to-br ${scoreBg(scoreData.score)} text-white`}>
                <div className="text-xs font-bold uppercase tracking-wider opacity-80">Your Health Score</div>
                <div className="font-display text-7xl mt-2">{scoreData.score}</div>
                <div className="text-lg font-semibold mt-1">/ 100</div>
                <div className="mt-3 inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-white/25 text-sm font-bold">
                  <Sparkles className="w-4 h-4" /> {scoreData.category}
                </div>
              </div>
              <div className="glass rounded-3xl p-5">
                <h3 className="font-display text-lg mb-3 flex items-center gap-2">
                  <TrendingUp className="w-4 h-4 text-emerald-500" /> Improvement Tips
                </h3>
                <ul className="space-y-2">
                  {scoreData.tips?.map((tip, i) => (
                    <li key={i} className="text-sm text-slate-600 flex items-start gap-2">
                      <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 mt-2 shrink-0" />{tip}
                    </li>
                  ))}
                </ul>
              </div>
              <div className="glass rounded-3xl p-5">
                <h3 className="font-display text-lg mb-3">Breakdown</h3>
                <div className="space-y-2">
                  {Object.entries(scoreData.breakdown || {}).map(([key, val]) => (
                    <div key={key}>
                      <div className="flex justify-between text-xs mb-1">
                        <span className="capitalize text-slate-600">{key.replace(/_/g, " ")}</span>
                        <span className="font-bold">{val.value}</span>
                      </div>
                      <div className="h-2 rounded-full bg-slate-100 overflow-hidden">
                        <div className="h-full rounded-full bg-gradient-to-r from-emerald-400 to-teal-500"
                          style={{ width: `${Math.min(100, (val.score / 15) * 100)}%` }} />
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </>
          ) : (
            <div className="glass rounded-3xl p-10 text-center">
              <div className="w-20 h-20 mx-auto rounded-full bg-emerald-100 grid place-items-center mb-4">
                <Activity className="w-8 h-8 text-emerald-600" strokeWidth={2} />
              </div>
              <h2 className="font-display text-xl mb-2">Calculate your score</h2>
              <p className="text-sm text-slate-500">Enter your health metrics to get a personalized health score.</p>
            </div>
          )}
        </div>
      </div>

      {scoreData && (
        <div className="mt-6 glass rounded-3xl p-4 text-xs text-slate-500">
          This is a heuristic wellness score. Not a medical diagnosis. Consult a healthcare professional.
        </div>
      )}
    </div>
  );
}
